                                visited[nr][nc] = True
                                stack.append((nr, nc))
                height = max_r - min_r + 1
                width = max_c - min_c + 1
                touches_border = (min_r == 0 or max_r == R - 1 or min_c == 0 or max_c == C - 1)
                components.append({
                    'color': color,
                    'min_r': min_r,
                    'min_c': min_c,
                    'height': height,
                    'width': width,
                    'touches': touches_border
                })

    # Keep only components that touch the border
    border_comps = [c for c in components if c['touches']]
    if not border_comps:
        return []

    # Determine orientation: vertical if any border component is taller than wide
    orientation = 'vertical' if any(c['height'] > c['width'] for c in border_comps) else 'horizontal'

    # Deduplicate colors: keep the component with smallest row (horizontal) or column (vertical)
    color_map = {}
    for c in border_comps:
        col = c['color']
        if col not in color_map:
            color_map[col] = c
        else:
            other = color_map[col]
            if orientation == 'horizontal':
                if c['min_r'] < other['min_r']:
                    color_map[col] = c
            else:
                if c['min_c'] < other['min_c']:
                    color_map[col] = c

    # Sort by the appropriate coordinate
    unique_comps = list(color_map.values())
    if orientation == 'horizontal':
        unique_comps.sort(key=lambda c: c['min_r'])
    else:
        unique_comps.sort(key=lambda c: c['min_c'])

    colors = [c['color'] for c in unique_comps]
    N = len(colors)

    # Build the output grid
    if orientation == 'horizontal':
        # each row is constant
        output = [[colors[i] for _ in range(N)] for i in range(N)]
    else:
        # each column is constant -> every row is the same list of colors
        output = [colors[:] for _ in range(N)]

    return output

